// The station as NeuronCore drew and lit it before the engine moved to Direct3D's axes (Design/Archive/NeuronVoxelFormat.md
// §12.4): pinned once, and compared ever after. Everything here is in MagicaVoxel's axes, right-handed with +Z up, as
// the engine used them then; the tests swap it into the engine's. A throwaway program generated it from the tree at
// 3c7dc2b with NeuronCore's tracer, explosion and lighting, compiled by GCC 13.3 at -O2 for x86-64. The explosion's
// flights and the ground's half of the lighting's column were pinned too; they retired with the gravity and the ground
// they pinned (Design/ADR/ADR-013), and what is left is as it was generated.

// The station's lighting, as its file's render objects gave it until the lighting came from the world
// (Design/ADR/ADR-008, Design/Archive/SpaceScene.md §12.1), and as the pins were taken under it: a white sun at _angle 50 50 and
// _i 0.7, a white sky at _i 0.7, the ground's sRGB 80 as the ambient's lower color, and a black background.
[[nodiscard]] inline NeuronCore::LightingParameters StationLighting(float _emissiveGain) noexcept
{
  constexpr float SUN_RADIANS = 50.0f * 0.0174532925f;
  const float ground = NeuronCore::SrgbToLinear(80);
  return {NeuronCore::SunDirection(SUN_RADIANS, SUN_RADIANS),
          {0.7f, 0.7f, 0.7f},
          {1.0f, 1.0f, 1.0f},
          0.7f,
          {ground, ground, ground},
          {0.0f, 0.0f, 0.0f},
          _emissiveGain};
}

// The cameras of the view splat tests: the application's field of view and near plane (SampleRenderer §3, §7.5), and
// an odd-sized image, so that a level camera has a whole row and column of rays with exactly-zero components.
inline constexpr float PINNED_FOV_Y_RADIANS = 0.785398163f;
inline constexpr float PINNED_NEAR_PLANE = 0.1f;
inline constexpr std::uint32_t PINNED_WIDTH_PIXELS = 161;
inline constexpr std::uint32_t PINNED_HEIGHT_PIXELS = 91;
inline constexpr NeuronCore::Float3 PINNED_TARGET{0.5f, 0.5f, 127.5f}; // the middle of the station's box
inline constexpr NeuronCore::Float3 PINNED_UP{0.0f, 0.0f, 1.0f};

// The sun's view of the station's box, as MakeShadowView fits it: this many texels across a square twice this wide.
inline constexpr std::uint32_t PINNED_SUN_PIXELS = 91;
inline constexpr float PINNED_SUN_HALF_EXTENT = 160.0f;

// A pixel of a pinned image that shows a voxel: its index, row by row, and the voxel's record index. A pixel the list
// leaves out shows none.
struct PinnedPixel
{
  std::uint32_t pixel;
  std::uint32_t voxel;
};

